-- Migration 0016 — Phase 6: payment state machine + UNKNOWN/reconciliation
-- (gap register D4, D11, PHASE3-02, PHASE4-03).
--
-- Generated by `drizzle-kit generate` from src/schema/transactions.ts; this
-- header and the data-normalising UPDATE before the CHECK constraint were
-- added by hand.
--
-- 1. Reconciliation bookkeeping columns (all nullable / defaulted — existing
--    rows are untouched by the ADD COLUMNs):
--      outcome_unknown_at, reconciliation_reason, reconciliation_required_at,
--      reconciliation_checked_at, reconciliation_check_count,
--      reconciliation_last_check, reconciliation_resolved_at,
--      reconciliation_resolution
--    (meaning documented in src/schema/transactions.ts).
-- 2. idx_transactions_unresolved: partial index for the reconciliation sweep.
-- 3. chk_transactions_status: Postgres itself now rejects any status outside
--    the state machine in src/transaction-status.ts.
--
-- Existing data is never deleted or silently rewritten. Before the CHECK
-- constraint is added, a row whose status is outside the new set (it could
-- only have been written by code older than this state machine) is moved to
-- 'requires_reconciliation' — the operator review list — with its original
-- status preserved verbatim in reconciliation_reason, rather than failing the
-- migration or guessing what the old value meant. Every status the platform
-- has ever written ('pending', 'processing', 'success', 'failed', 'refunded',
-- 'cancelled', 'unknown') is in the new set and is left exactly as it is.
-- Legacy 'pending' rows (which is how the gateway stored ambiguous provider
-- outcomes before Phase 6 — D4) are picked up by the reconciliation sweep
-- once stale, not rewritten here.
--
-- NOTE ON THE JOURNAL TIMESTAMP: drizzle-kit stamped this entry with the
-- wall-clock time, which is EARLIER than 0015's hand-set "when"
-- (1792100000000); drizzle-orm's migrator skips a migration whose "when" is
-- not newer than the last one applied, so _journal.json was set to
-- 1792200000000 — the same trap and fix as migrations 0013-0015.

ALTER TABLE "transactions" ADD COLUMN "outcome_unknown_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "transactions" ADD COLUMN "reconciliation_reason" text;--> statement-breakpoint
ALTER TABLE "transactions" ADD COLUMN "reconciliation_required_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "transactions" ADD COLUMN "reconciliation_checked_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "transactions" ADD COLUMN "reconciliation_check_count" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "transactions" ADD COLUMN "reconciliation_last_check" jsonb;--> statement-breakpoint
ALTER TABLE "transactions" ADD COLUMN "reconciliation_resolved_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "transactions" ADD COLUMN "reconciliation_resolution" jsonb;--> statement-breakpoint
CREATE INDEX "idx_transactions_unresolved" ON "transactions" USING btree ("updated_at") WHERE "transactions"."status" IN ('processing', 'pending', 'requires_action', 'unknown', 'requires_reconciliation');--> statement-breakpoint
UPDATE "transactions" SET "status" = 'requires_reconciliation', "outcome_unknown_at" = COALESCE("outcome_unknown_at", now()), "reconciliation_required_at" = now(), "reconciliation_reason" = 'migration 0016: unexpected legacy status ' || quote_literal("status"), "updated_at" = now() WHERE "status" NOT IN ('processing', 'pending', 'requires_action', 'success', 'failed', 'cancelled', 'partially_refunded', 'refunded', 'unknown', 'requires_reconciliation');--> statement-breakpoint
ALTER TABLE "transactions" ADD CONSTRAINT "chk_transactions_status" CHECK ("transactions"."status" IN ('processing', 'pending', 'requires_action', 'success', 'failed', 'cancelled', 'partially_refunded', 'refunded', 'unknown', 'requires_reconciliation'));